<script lang="ts">
import {Field, Select, SegmentedControl, Button, Badge, EmptyState, StatGroup} from '../../design-system/svelte';
import FullExamples from './FullExamples.svelte';
import Recipe from './Recipe.svelte';import CodeExample from './CodeExample.svelte';
import {recipes} from './recipes';import {baselines} from './baselines';
let selected=$state('navigation'),query=$state(''),baselineQuery=$state(''),variant=$state('light'),scenario=$state('01-09-scene-selected');
const filtered=$derived(recipes.filter(r=>`${r.title} ${r.description} ${r.components.join(' ')}`.toLowerCase().includes(query.toLowerCase())));
const scenarios=baselines.filter(b=>b.variant==='light');
const available=$derived(scenarios.filter(b=>`${b.scenario} ${b.expect}`.toLowerCase().includes(baselineQuery.toLowerCase())));
const selectedScenario=$derived(available.some(b=>b.scenario===scenario)?scenario:available[0]?.scenario);
const baseline=$derived(baselines.find(b=>b.scenario===selectedScenario&&b.variant===variant));
const label=(s:string)=>s.replace(/^\d+-\d+-/,'').replaceAll('-',' ');
function choose(id:string){selected=id;scenario=recipes.find(r=>r.id===id)!.baseline;baselineQuery='';}
</script>
